/* Unicode character properties and case mappings for (scheme char)
 * (R7RS 6.6, 6.7; docs/design-l6.md Part U). Tables are generated by
 * tools/gen_unicode.py (runtime/unicode_tables.h). The policy (which
 * procedure uses which mapping, final sigma) lives in lib/scheme/char.sld;
 * these primitives are table lookups. */

#include "npl.h"
#include "unicode_tables.h"
#include <stdlib.h>

#define COUNT(table) (sizeof(table) / sizeof((table)[0]))

static int in_ranges(const uint32_t (*ranges)[2], size_t count, uint32_t code)
{
    size_t low = 0, high = count;
    while (low < high) {
        size_t middle = low + (high - low) / 2;
        if (code < ranges[middle][0]) high = middle;
        else if (code > ranges[middle][1]) low = middle + 1;
        else return 1;
    }
    return 0;
}

static int map_lookup(const uint32_t (*map)[2], size_t count, uint32_t code,
                      uint32_t *target)
{
    size_t low = 0, high = count;
    while (low < high) {
        size_t middle = low + (high - low) / 2;
        if (code < map[middle][0]) high = middle;
        else if (code > map[middle][0]) low = middle + 1;
        else { *target = map[middle][1]; return 1; }
    }
    return 0;
}

static const uint32_t *full_lookup(const uint32_t (*map)[5], size_t count,
                                   uint32_t code)
{
    size_t low = 0, high = count;
    while (low < high) {
        size_t middle = low + (high - low) / 2;
        if (code < map[middle][0]) high = middle;
        else if (code > map[middle][0]) low = middle + 1;
        else return map[middle];
    }
    return NULL;
}

static uint32_t char_argument(NplVal value, const char *who)
{
    if (!npl_is_char(value))
        npl_primitive_error(who, "expected a character", value);
    return npl_char_value(value);
}

/* (npl_char_property character kind): kind 0 alphabetic, 1 numeric
 * (Numeric_Type=Decimal), 2 whitespace, 3 uppercase, 4 lowercase, 5 cased,
 * 6 case-ignorable (the last two for the Final_Sigma rule). */
NplVal npl_char_property(NplVal character, NplVal kind)
{
    uint32_t code = char_argument(character, "char property");
    uint32_t ignored;
    int result;
    switch (npl_is_fixnum(kind) ? npl_fixnum_value(kind) : -1) {
    case 0: result = in_ranges(npl_alphabetic_ranges,
                               COUNT(npl_alphabetic_ranges), code); break;
    case 1: result = map_lookup(npl_decimal_digits,
                                COUNT(npl_decimal_digits), code, &ignored);
            break;
    case 2: result = in_ranges(npl_whitespace_ranges,
                               COUNT(npl_whitespace_ranges), code); break;
    case 3: result = in_ranges(npl_uppercase_ranges,
                               COUNT(npl_uppercase_ranges), code); break;
    case 4: result = in_ranges(npl_lowercase_ranges,
                               COUNT(npl_lowercase_ranges), code); break;
    case 5: result = in_ranges(npl_cased_ranges,
                               COUNT(npl_cased_ranges), code); break;
    case 6: result = in_ranges(npl_case_ignorable_ranges,
                               COUNT(npl_case_ignorable_ranges), code); break;
    default:
        npl_primitive_error("char property", "invalid property", kind);
        return npl_nil();
    }
    return result ? npl_true() : npl_false();
}

/* digit-value: the decimal digit value, or #f. */
NplVal npl_char_digit_value(NplVal character)
{
    uint32_t code = char_argument(character, "digit-value");
    uint32_t digit;
    return map_lookup(npl_decimal_digits, COUNT(npl_decimal_digits), code,
                      &digit) ? npl_fixnum(digit) : npl_false();
}

/* (npl_char_case character kind): simple mapping; kind 0 upcase,
 * 1 downcase, 2 foldcase. Unmapped characters map to themselves. */
NplVal npl_char_case(NplVal character, NplVal kind)
{
    uint32_t code = char_argument(character, "char case");
    uint32_t target = code;
    switch (npl_is_fixnum(kind) ? npl_fixnum_value(kind) : -1) {
    case 0: map_lookup(npl_simple_upper, COUNT(npl_simple_upper), code,
                       &target); break;
    case 1: map_lookup(npl_simple_lower, COUNT(npl_simple_lower), code,
                       &target); break;
    case 2: map_lookup(npl_simple_fold, COUNT(npl_simple_fold), code,
                       &target); break;
    default:
        npl_primitive_error("char case", "invalid mapping", kind);
    }
    return npl_char(target);
}

/* (npl_char_full_case character kind): the full mapping (kind as above) as
 * a list of characters, for string-upcase/downcase/foldcase. */
NplVal npl_char_full_case(NplVal character, NplVal kind)
{
    uint32_t code = char_argument(character, "string case");
    const uint32_t *row = NULL;
    switch (npl_is_fixnum(kind) ? npl_fixnum_value(kind) : -1) {
    case 0: row = full_lookup(npl_full_upper, COUNT(npl_full_upper), code);
            break;
    case 1: row = full_lookup(npl_full_lower, COUNT(npl_full_lower), code);
            break;
    case 2: row = full_lookup(npl_full_fold, COUNT(npl_full_fold), code);
            break;
    default:
        npl_primitive_error("string case", "invalid mapping", kind);
    }
    if (!row)
        return npl_cons(npl_char_case(character, kind), npl_nil());
    NplVal result = npl_nil();
    for (uint32_t i = row[1]; i > 0; i--)
        result = npl_cons(npl_char(row[1 + i]), result);
    return result;
}
